        for num in numbers:
            str_numbers.append(str(num))

        # Calculate partial products iteratively
        partial_products = [1]
        current_product = 1
        for num in numbers:
            current_product *= num
            partial_products.append(current_product)

        # Remove the initial '1' from partial_products to get the sequence of actual products
        # This uses comprehension to filter and create a new list
        final_products = []
        for p in partial_products:
            if p > 1 or n == 1:
                final_products.append(p)

        # Create a list of squares of the numbers (another comprehension)
        squares = []
        for num in numbers:
            squares.append(num * num)

        return final_products[-1]

